      width: 36px;
      height: 36px;
      place-items: center;
      color: #06101a;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      border-radius: 50%;
      box-shadow: 0 10px 28px rgba(141, 220, 255, 0.22);
      transition: transform 200ms ease;
    }

    .example.is-open .icon {
