    }

    .example.is-open .answer {
      grid-template-rows: 1fr;
    }

    .answer-inner {
      overflow: hidden;
    }

    .answer p {
      margin: 0;
      padding: 0 24px 24px;
      color: var(--muted);
    }

    .answer strong {
      color: #dfe9ff;
      font-weight: 700;
    }

    @media (max-width: 640px) {
      .app {
        width: min(100% - 20px, 920px);
        padding: 42px 0;
      }

      .details {
        padding: 8px;
        border-radius: 22px;
      }

      .question {
        padding: 18px;
      }

      .answer p {
        padding: 0 18px 20px;
      }
    }
  </style>
</head>
<body>
  <main id="root"></main>

  <script>
    const faqs = [
      {
        question: "Why do cats purr?",
        answer: "Cats often purr when they feel safe and content, but purring can also be self-soothing. Some cats purr when they are stressed, healing, or asking for attention."
      },
      {
        question: "How much sleep do cats need?",
        answer: "Most adult cats sleep <strong>12 to 16 hours a day</strong>, while kittens and senior cats may sleep even more. Their crepuscular nature makes them most active around dawn and dusk."
      },
      {
        question: "Why does my cat knead blankets or my lap?",
        answer: "Kneading is a comfort behavior that begins in kittenhood. Adult cats may knead soft surfaces when they are relaxed, marking a favorite spot, or settling in for a nap."
      },
      {
        question: "Should indoor cats still see a veterinarian?",
        answer: "Yes. Indoor cats still need wellness exams, dental checks, parasite prevention guidance, and vaccines based on their lifestyle and local veterinary recommendations."
      },
      {
        question: "Why do cats knock things off tables?",
        answer: "Cats explore with their paws, test movement, and sometimes learn that dropped objects get a fast human reaction. Enrichment toys and play sessions can redirect that curiosity."
      },
      {
        question: "What is the best way to introduce a new cat?",
        answer: "Go slowly: keep cats separated at first, swap scents, use short supervised meetings, and reward calm behavior. Patience helps prevent territorial stress and builds trust."
      }
    ];

    function Header() {
      return `
        <section class="hero" aria-labelledby="page-title">
          <p class="eyebrow">Cat Care Guide</p>
          <h1 id="page-title">Frequently Asked Cat Questions</h1>
          <p class="intro">
            Quick, practical answers for curious cat people. Select a question to expand the answer.
          </p>
        </section>
      `;
    }

    function FAQItem(item, index) {
      const buttonId = `faq-question-${index}`;
      const panelId = `faq-answer-${index}`;

      return `
        <div class="example">
          <button
            class="question"
            type="button"
            id="${buttonId}"
            aria-expanded="false"
            aria-controls="${panelId}"
          >
            <span class="question-text">${item.question}</span>
            <span class="icon" aria-hidden="true">+</span>
          </button>
          <div
            class="answer"
            id="${panelId}"
            role="region"
            aria-labelledby="${buttonId}"
            hidden
          >
            <div class="answer-inner">
              <p>${item.answer}</p>
            </div>
          </div>
        </div>
      `;
    }

    function FAQList(items) {
      return `
        <section class="details" aria-label="Cat FAQ">
          ${items.map(FAQItem).join("")}
        </section>
      `;
    }

    function App() {
      return `
        <div class="app">
          ${Header()}
          ${FAQList(faqs)}
        </div>
      `;
    }

    function attachFAQControls(root) {
      root.querySelectorAll(".example").forEach((item) => {
        const button = item.querySelector(".question");
